'use client';

import * as React from 'react';
import { cn } from '@/lib/utils';

export interface BranchProps {
  /** Total number of message variants. Renders nothing when count < 2. */
  count: number;
  /** Zero-based index of the currently displayed variant. */
  selected?: number;
  /** Uncontrolled initial variant when `selected` is omitted. */
  defaultSelected?: number;
  onSelect?: (index: number) => void;
  labels?: { previous?: string; next?: string };
  className?: string;
}

/**
 * Variant navigation for branched messages (`‹ 2 / 3 ›`).
 * Purely presentational + minimal internal state; the consumer swaps content.
 */
const Branch = React.forwardRef<HTMLDivElement, BranchProps>(
  (
    { count, selected, defaultSelected = 0, onSelect, labels, className, ...props },
    ref
  ) => {
    const [internalIndex, setInternalIndex] = React.useState(defaultSelected);
    const isControlled = selected !== undefined;
    const index = Math.min(Math.max(isControlled ? selected : internalIndex, 0), count - 1);

    const t = {
      previous: labels?.previous ?? 'Previous response',
      next: labels?.next ?? 'Next response',
    };

    if (count < 2) return null;

    const goTo = (next: number) => {
      const clamped = Math.min(Math.max(next, 0), count - 1);
      if (!isControlled) setInternalIndex(clamped);
      onSelect?.(clamped);
    };

    return (
      <div
        ref={ref}
        className={cn('flex items-center gap-1 text-xs text-muted-foreground', className)}
        {...props}
      >
        <button
          type="button"
          onClick={() => goTo(index - 1)}
          disabled={index === 0}
          aria-label={t.previous}
          className="rounded px-1 hover:bg-accent hover:text-foreground transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring disabled:opacity-40"
        >
          ‹
        </button>
        <span aria-live="polite" className="tabular-nums">
          {index + 1} / {count}
        </span>
        <button
          type="button"
          onClick={() => goTo(index + 1)}
          disabled={index === count - 1}
          aria-label={t.next}
          className="rounded px-1 hover:bg-accent hover:text-foreground transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring disabled:opacity-40"
        >
          ›
        </button>
      </div>
    );
  }
);
Branch.displayName = 'Branch';

export { Branch };

{
  "id": "branch",
  "name": "Branch",
  "tier": "atom",
  "description": "Variant navigation for branched messages: previous/next arrows with an N/M position indicator.",
  "designIntent": "Let users compare alternative AI responses without leaving the transcript flow.",
  "props": [
    {
      "name": "count",
      "type": "number",
      "required": true,
      "description": "Total variants; renders nothing below 2."
    },
    {
      "name": "selected",
      "type": "number",
      "required": false,
      "description": "Controlled zero-based index."
    },
    {
      "name": "defaultSelected",
      "type": "number",
      "defaultValue": 0,
      "required": false,
      "description": "Uncontrolled initial index."
    },
    {
      "name": "onSelect",
      "type": "(index: number) => void",
      "required": false,
      "description": "Called with the chosen variant index."
    },
    {
      "name": "labels",
      "type": "object",
      "required": false,
      "description": "Overrides for previous/next aria-labels."
    }
  ],
  "examples": [
    {
      "title": "Two variants",
      "code": "<Branch count={variants.length} selected={i} onSelect={setI} />"
    }
  ],
  "antiPatterns": [
    {
      "title": "Do not swap message content without syncing selected",
      "explanation": "In controlled mode the displayed variant must follow onSelect."
    }
  ],
  "accessibility": [
    {
      "feature": "Boundary disabling",
      "implementation": "Arrows disable at ends instead of wrapping silently."
    },
    {
      "feature": "Position announcement",
      "implementation": "N/M indicator uses aria-live=polite."
    }
  ],
  "package": "@slipstream-ui/ai",
  "importPath": "@slipstream-ui/ai",
  "version": "0.0.1"
}
